/**
 * SQLite schema for the single-owner (Home Assistant add-on) build.
 *
 * Derived from the final state of the 38 migrations of the upstream hosted
 * service (Postgres; every later ALTER TABLE folded in), keeping the 16 tables
 * the add-on needs. The hosted service's auth, token and usage-log tables are
 * not part of this build — see step-A1-report.md for the list.
 *
 * Type mapping: uuid -> TEXT (generated by DEFAULT, uuid v4 shape),
 * timestamptz -> TEXT ISO-8601 UTC with millisecond precision and a trailing
 * "Z" (so string order == time order; every writer normalises through
 * `new Date(x).toISOString()`), date -> TEXT 'YYYY-MM-DD', integer/smallint ->
 * INTEGER (STRICT tables reject fractional values, as Postgres did),
 * numeric -> REAL, jsonb -> TEXT (CHECK json_type), text[] -> TEXT JSON array,
 * boolean -> INTEGER 0/1.
 *
 * Row-level security is replaced by an explicit `user_id` predicate in every
 * repo query. There is no users table, so user_id carries no foreign key; the
 * only value ever written is OWNER_ID (src/db/owner.ts).
 */

const UUID = `(lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6))))`;
const NOW = `(strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))`;

// Every table is STRICT: SQLite then enforces the declared column type like
// Postgres did (a non-integral REAL into an INTEGER column, or text into a
// REAL/INTEGER column, is an error), which replaces the per-column "is
// integral" CHECKs of the first draft. STRICT needs SQLite >= 3.37.
/** An ISO-8601 UTC instant as every writer stores it (see util.ts ts()). */
const isoTs = (col: string) =>
    `CHECK (${col} IS NULL OR ${col} GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]*Z')`;
/** A calendar date, YYYY-MM-DD. */
const isoDate = (col: string) =>
    `CHECK (${col} IS NULL OR ${col} GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]')`;
const jsonObj = (col: string) =>
    `CHECK (${col} IS NULL OR json_type(${col}) = 'object')`;

/** Nutrient columns shared by meals / saved_meals / their item tables. */
function nutrientColumns(opts: {
    calories: string;
    required: boolean;
    /** meals.protein_g/carbs_g/fat_g carry no CHECK upstream (only the later
     *  columns do); the item and saved-meal tables do. */
    macroCheck: boolean;
}): string {
    const req = opts.required ? "NOT NULL" : "";
    const macro = (n: string) =>
        `${n} REAL ${req}${opts.macroCheck ? ` CHECK (${n} >= 0)` : ""}`;
    const opt = (n: string) => `${n} REAL CHECK (${n} >= 0)`;
    return [
        opts.calories,
        macro("protein_g"),
        macro("carbs_g"),
        macro("fat_g"),
        opt("saturated_fat_g"),
        opt("trans_fat_g"),
        opt("fiber_g"),
        opt("sugar_g"),
        opt("added_sugar_g"),
        opt("alcohol_g"),
        opt("caffeine_mg"),
        opt("sodium_mg"),
    ].join(",\n    ");
}

const V1 = `
CREATE TABLE saved_meals (
    id TEXT PRIMARY KEY DEFAULT ${UUID},
    user_id TEXT NOT NULL,
    name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 100),
    -- lower(name) as computed in JS (Unicode-aware, like Postgres lower()):
    -- carries the case-insensitive uniqueness uniq_saved_meals_user_name had.
    name_key TEXT NOT NULL,
    description TEXT NOT NULL CHECK (length(description) BETWEEN 1 AND 2000),
    meal_type TEXT CHECK (meal_type IN ('breakfast', 'lunch', 'dinner', 'snack')),
    ${nutrientColumns({ calories: "calories INTEGER CHECK (calories >= 0)", required: false, macroCheck: true })},
    nutrient_sources TEXT ${jsonObj("nutrient_sources")},
    source_detail TEXT ${jsonObj("source_detail")},
    created_at TEXT NOT NULL DEFAULT ${NOW} ${isoTs("created_at")},
    updated_at TEXT NOT NULL DEFAULT ${NOW} ${isoTs("updated_at")}
) STRICT;
CREATE UNIQUE INDEX uniq_saved_meals_user_name ON saved_meals (user_id, name_key);
CREATE INDEX idx_saved_meals_user ON saved_meals (user_id);

CREATE TABLE meals (
    id TEXT PRIMARY KEY DEFAULT ${UUID},
    user_id TEXT NOT NULL,
    logged_at TEXT NOT NULL DEFAULT ${NOW} ${isoTs("logged_at")},
    meal_type TEXT CHECK (meal_type IN ('breakfast', 'lunch', 'dinner', 'snack')),
    description TEXT NOT NULL,
    ${nutrientColumns({ calories: "calories INTEGER", required: false, macroCheck: false })},
    notes TEXT,
    idempotency_key TEXT,
    saved_meal_id TEXT REFERENCES saved_meals (id) ON DELETE SET NULL,
    nutrient_sources TEXT ${jsonObj("nutrient_sources")},
    source_detail TEXT ${jsonObj("source_detail")}
) STRICT;
CREATE UNIQUE INDEX uniq_meals_user_idem ON meals (user_id, idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE INDEX idx_meals_user_logged_at ON meals (user_id, logged_at);
CREATE INDEX idx_meals_saved_meal_id ON meals (saved_meal_id) WHERE saved_meal_id IS NOT NULL;

CREATE TABLE meal_items (
    id TEXT PRIMARY KEY DEFAULT ${UUID},
    meal_id TEXT NOT NULL REFERENCES meals (id) ON DELETE CASCADE,
    user_id TEXT NOT NULL,
    position INTEGER NOT NULL CHECK (position >= 1),
    name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    amount REAL CHECK (amount > 0),
    unit TEXT CHECK (length(unit) BETWEEN 1 AND 20),
    ${nutrientColumns({ calories: "calories REAL NOT NULL CHECK (calories >= 0)", required: true, macroCheck: true })},
    nutrient_sources TEXT ${jsonObj("nutrient_sources")},
    source_detail TEXT ${jsonObj("source_detail")},
    UNIQUE (meal_id, position)
) STRICT;
CREATE INDEX idx_meal_items_user ON meal_items (user_id);

CREATE TABLE saved_meal_items (
    id TEXT PRIMARY KEY DEFAULT ${UUID},
    saved_meal_id TEXT NOT NULL REFERENCES saved_meals (id) ON DELETE CASCADE,
    user_id TEXT NOT NULL,
    position INTEGER NOT NULL CHECK (position >= 1),
    name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    amount REAL CHECK (amount > 0),
    unit TEXT CHECK (length(unit) BETWEEN 1 AND 20),
    ${nutrientColumns({ calories: "calories REAL NOT NULL CHECK (calories >= 0)", required: true, macroCheck: true })},
    nutrient_sources TEXT ${jsonObj("nutrient_sources")},
    source_detail TEXT ${jsonObj("source_detail")},
    UNIQUE (saved_meal_id, position)
) STRICT;
CREATE INDEX idx_saved_meal_items_user ON saved_meal_items (user_id);

-- numeric(6,2) / numeric(7,2) goal columns: the repo rounds to 2 decimals on
-- write, as Postgres does.
CREATE TABLE nutrition_goals (
    user_id TEXT PRIMARY KEY,
    daily_calories INTEGER,
    daily_protein_g REAL,
    daily_carbs_g REAL,
    daily_fat_g REAL,
    daily_saturated_fat_g REAL CHECK (daily_saturated_fat_g >= 0),
    daily_fiber_g REAL CHECK (daily_fiber_g >= 0),
    daily_sugar_g REAL CHECK (daily_sugar_g >= 0),
    daily_added_sugar_g REAL CHECK (daily_added_sugar_g >= 0),
    daily_alcohol_g REAL CHECK (daily_alcohol_g >= 0),
    daily_caffeine_mg REAL CHECK (daily_caffeine_mg >= 0),
    daily_sodium_mg REAL CHECK (daily_sodium_mg >= 0),
    daily_water_ml INTEGER,
    target_weight_g INTEGER CHECK (target_weight_g > 0) ,
    updated_at TEXT NOT NULL DEFAULT ${NOW} ${isoTs("updated_at")}
) STRICT;

CREATE TABLE nutrition_goals_history (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id TEXT NOT NULL,
    effective_at TEXT NOT NULL DEFAULT ${NOW} ${isoTs("effective_at")},
    daily_calories INTEGER,
    daily_protein_g REAL,
    daily_carbs_g REAL,
    daily_fat_g REAL,
    daily_saturated_fat_g REAL CHECK (daily_saturated_fat_g >= 0),
    daily_fiber_g REAL CHECK (daily_fiber_g >= 0),
    daily_sugar_g REAL CHECK (daily_sugar_g >= 0),
    daily_added_sugar_g REAL CHECK (daily_added_sugar_g >= 0),
    daily_alcohol_g REAL CHECK (daily_alcohol_g >= 0),
    daily_caffeine_mg REAL CHECK (daily_caffeine_mg >= 0),
    daily_sodium_mg REAL CHECK (daily_sodium_mg >= 0),
    daily_water_ml INTEGER,
    target_weight_g INTEGER CHECK (target_weight_g > 0)
) STRICT;
CREATE INDEX idx_nutrition_goals_history_user_effective_at ON nutrition_goals_history (user_id, effective_at);

CREATE TABLE water_log (
    id TEXT PRIMARY KEY DEFAULT ${UUID},
    user_id TEXT NOT NULL,
    amount_ml INTEGER NOT NULL CHECK (amount_ml > 0),
    logged_at TEXT NOT NULL DEFAULT ${NOW} ${isoTs("logged_at")},
    notes TEXT,
    created_at TEXT NOT NULL DEFAULT ${NOW} ${isoTs("created_at")},
    idempotency_key TEXT
) STRICT;
CREATE INDEX idx_water_log_user_logged_at ON water_log (user_id, logged_at);
CREATE UNIQUE INDEX uniq_water_log_user_idem ON water_log (user_id, idempotency_key) WHERE idempotency_key IS NOT NULL;

CREATE TABLE weight_log (
    id TEXT PRIMARY KEY DEFAULT ${UUID},
    user_id TEXT NOT NULL,
    weight_g INTEGER NOT NULL CHECK (weight_g > 0),
    logged_at TEXT NOT NULL DEFAULT ${NOW} ${isoTs("logged_at")},
    notes TEXT,
    created_at TEXT NOT NULL DEFAULT ${NOW} ${isoTs("created_at")},
    idempotency_key TEXT
) STRICT;
CREATE INDEX idx_weight_log_user_logged_at ON weight_log (user_id, logged_at);
CREATE UNIQUE INDEX uniq_weight_log_user_idem ON weight_log (user_id, idempotency_key) WHERE idempotency_key IS NOT NULL;

CREATE TABLE body_measurement_log (
    id TEXT PRIMARY KEY DEFAULT ${UUID},
    user_id TEXT NOT NULL,
    kind TEXT NOT NULL CHECK (kind IN ('waist', 'hips', 'neck', 'chest', 'shoulders', 'upper_arm', 'forearm', 'thigh', 'calf')),
    value_mm INTEGER NOT NULL CHECK (value_mm > 0),
    value_entered REAL NOT NULL CHECK (value_entered > 0),
    entered_unit TEXT NOT NULL CHECK (entered_unit IN ('cm', 'in')),
    logged_at TEXT NOT NULL DEFAULT ${NOW} ${isoTs("logged_at")},
    notes TEXT,
    created_at TEXT NOT NULL DEFAULT ${NOW} ${isoTs("created_at")},
    idempotency_key TEXT
) STRICT;
CREATE INDEX idx_body_measurement_log_user_logged_at ON body_measurement_log (user_id, logged_at);
CREATE UNIQUE INDEX uniq_body_measurement_log_user_idem ON body_measurement_log (user_id, idempotency_key) WHERE idempotency_key IS NOT NULL;

CREATE TABLE active_calories_log (
    id TEXT PRIMARY KEY DEFAULT ${UUID},
    user_id TEXT NOT NULL,
    logged_at TEXT NOT NULL DEFAULT ${NOW} ${isoTs("logged_at")},
    kcal INTEGER NOT NULL CHECK (kcal BETWEEN 1 AND 10000),
    credit_pct INTEGER NOT NULL CHECK (credit_pct BETWEEN 0 AND 100),
    notes TEXT,
    idempotency_key TEXT,
    created_at TEXT NOT NULL DEFAULT ${NOW} ${isoTs("created_at")},
    source TEXT CHECK (source IN ('apple_health')),
    source_date TEXT ${isoDate("source_date")},
    CONSTRAINT active_calories_log_source_date_check CHECK ((source IS NULL) = (source_date IS NULL))
) STRICT;
CREATE INDEX idx_active_calories_log_user_logged_at ON active_calories_log (user_id, logged_at);
CREATE UNIQUE INDEX uniq_active_calories_log_user_idem ON active_calories_log (user_id, idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE UNIQUE INDEX uniq_active_calories_log_health_day ON active_calories_log (user_id, source_date) WHERE source = 'apple_health';

-- One row per user. timezone / locale / the unit preferences are NULL until
-- chosen ("never set" is distinct from a default; see the readers in repo).
CREATE TABLE profiles (
    user_id TEXT PRIMARY KEY,
    timezone TEXT,
    preferred_weight_unit TEXT CHECK (preferred_weight_unit IS NULL OR preferred_weight_unit IN ('kg', 'lb')),
    preferred_length_unit TEXT CHECK (preferred_length_unit IS NULL OR preferred_length_unit IN ('cm', 'in')),
    widgets_enabled INTEGER NOT NULL DEFAULT 1 CHECK (widgets_enabled IN (0, 1)),
    alcohol_tracking_enabled INTEGER NOT NULL DEFAULT 0 CHECK (alcohol_tracking_enabled IN (0, 1)),
    preferred_drink_unit TEXT CHECK (preferred_drink_unit IS NULL OR preferred_drink_unit IN ('us', 'uk')),
    activity_credit_pct INTEGER CHECK (activity_credit_pct BETWEEN 0 AND 100),
    locale TEXT,
    created_at TEXT NOT NULL DEFAULT ${NOW} ${isoTs("created_at")},
    updated_at TEXT NOT NULL DEFAULT ${NOW} ${isoTs("updated_at")}
) STRICT;

CREATE TABLE food_cache (
    source TEXT NOT NULL,
    source_id TEXT NOT NULL,
    payload TEXT NOT NULL CHECK (json_valid(payload)),
    fetched_at TEXT NOT NULL DEFAULT ${NOW} ${isoTs("fetched_at")},
    PRIMARY KEY (source, source_id)
) STRICT;

CREATE TABLE health_sync_pending (
    id TEXT PRIMARY KEY DEFAULT ${UUID},
    kind TEXT NOT NULL DEFAULT 'health' CHECK (kind IN ('health', 'activity')),
    connect_id_hash TEXT NOT NULL UNIQUE,
    device_secret_hash TEXT NOT NULL,
    pkce_verifier TEXT,
    fields TEXT NOT NULL CHECK (json_type(fields) = 'array'),
    tz TEXT,
    backfill_days INTEGER NOT NULL DEFAULT 0 CHECK (backfill_days BETWEEN 0 AND 7),
    user_id TEXT,
    claim_code_hash TEXT UNIQUE,
    claim_expires_at TEXT ${isoTs("claim_expires_at")},
    created_at TEXT NOT NULL DEFAULT ${NOW} ${isoTs("created_at")},
    expires_at TEXT NOT NULL ${isoTs("expires_at")}
) STRICT;

CREATE TABLE health_sync_links (
    id TEXT PRIMARY KEY DEFAULT ${UUID},
    user_id TEXT NOT NULL UNIQUE,
    token_hash TEXT NOT NULL UNIQUE,
    kind TEXT NOT NULL DEFAULT 'shortcut' CHECK (kind IN ('shortcut')),
    fields TEXT NOT NULL CHECK (json_type(fields) = 'array'),
    fallback_tz TEXT,
    sync_start_date TEXT NOT NULL ${isoDate("sync_start_date")},
    lease_until TEXT ${isoTs("lease_until")},
    created_at TEXT NOT NULL DEFAULT ${NOW} ${isoTs("created_at")},
    last_used_at TEXT ${isoTs("last_used_at")},
    last_sync_at TEXT ${isoTs("last_sync_at")},
    expires_at TEXT NOT NULL ${isoTs("expires_at")}
) STRICT;

CREATE TABLE health_sync_days (
    user_id TEXT NOT NULL,
    date TEXT NOT NULL ${isoDate("date")},
    timezone TEXT NOT NULL,
    sent_values TEXT CHECK (sent_values IS NULL OR json_valid(sent_values)),
    topup_seq INTEGER NOT NULL DEFAULT 0,
    offer_count INTEGER NOT NULL DEFAULT 0,
    notified TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(notified)),
    first_sent_at TEXT ${isoTs("first_sent_at")},
    last_sent_at TEXT ${isoTs("last_sent_at")},
    PRIMARY KEY (user_id, date)
) STRICT;

CREATE TABLE health_activity_links (
    id TEXT PRIMARY KEY DEFAULT ${UUID},
    user_id TEXT NOT NULL UNIQUE,
    token_hash TEXT NOT NULL UNIQUE,
    fallback_tz TEXT,
    created_at TEXT NOT NULL DEFAULT ${NOW} ${isoTs("created_at")},
    last_used_at TEXT ${isoTs("last_used_at")},
    last_sync_at TEXT ${isoTs("last_sync_at")},
    expires_at TEXT NOT NULL ${isoTs("expires_at")}
) STRICT;
`;

// ---------------------------------------------------------------------------
// Migration 2: the hourly "sent so far" ledger for Apple Health sync.
//
// The shortcut now authenticates with one static key (no pairing, no per-link
// tokens), so the four link/pending tables go. The ledger changes shape too:
// instead of one JSON blob per day plus top-up bookkeeping, every day/field
// carries the running total Health already holds ("sent so far"), and the day
// carries a round counter that makes an entry id stable and an ack idempotent.
// No database existed when this ran for the first time (nothing to migrate).
// ---------------------------------------------------------------------------
const V2 = `
DROP TABLE health_sync_pending;
DROP TABLE health_sync_links;
DROP TABLE health_sync_days;
DROP TABLE health_activity_links;

-- One row per owner: the sync lease and the "last seen" clocks.
CREATE TABLE health_sync_state (
    user_id TEXT PRIMARY KEY,
    lease_until TEXT ${isoTs("lease_until")},
    last_sync_at TEXT ${isoTs("last_sync_at")},
    last_ack_at TEXT ${isoTs("last_ack_at")},
    last_activity_at TEXT ${isoTs("last_activity_at")}
) STRICT;

-- One row per local day that has had at least one acknowledged entry.
-- rounds = how many entries were acknowledged; the next entry id is rounds + 1.
CREATE TABLE health_sync_days (
    user_id TEXT NOT NULL,
    date TEXT NOT NULL ${isoDate("date")},
    timezone TEXT NOT NULL,
    rounds INTEGER NOT NULL DEFAULT 0 CHECK (rounds >= 0),
    first_sent_at TEXT ${isoTs("first_sent_at")},
    last_sent_at TEXT ${isoTs("last_sent_at")},
    PRIMARY KEY (user_id, date)
) STRICT;

-- "Sent so far": what Health holds from us for a day and field.
CREATE TABLE health_sync_sent (
    user_id TEXT NOT NULL,
    date TEXT NOT NULL ${isoDate("date")},
    field TEXT NOT NULL CHECK (field IN ('energy_kcal', 'protein_g', 'carbohydrates_g', 'fat_g', 'fiber_g', 'caffeine_mg', 'water_ml')),
    sent REAL NOT NULL CHECK (sent >= 0),
    PRIMARY KEY (user_id, date, field),
    FOREIGN KEY (user_id, date) REFERENCES health_sync_days (user_id, date) ON DELETE CASCADE
) STRICT;
`;

// ---------------------------------------------------------------------------
// Migration 3: dashboard login sessions (server-side, so logout and
// "sign out everywhere" really revoke). Not an owner table: a row holds no
// nutrition data, only the hash of a random session token.
// ---------------------------------------------------------------------------
const V3 = `
CREATE TABLE dashboard_sessions (
    -- SHA-256 (hex) of the random token in the cookie: a stolen database file
    -- cannot be turned back into a usable cookie.
    id TEXT PRIMARY KEY CHECK (length(id) = 64),
    -- Per-session CSRF token, embedded in every form the session is shown.
    csrf TEXT NOT NULL CHECK (length(csrf) >= 32),
    created_at TEXT NOT NULL ${isoTs("created_at")},
    last_seen_at TEXT NOT NULL ${isoTs("last_seen_at")},
    expires_at TEXT NOT NULL ${isoTs("expires_at")}
) STRICT;
CREATE INDEX idx_dashboard_sessions_expires ON dashboard_sessions (expires_at);
`;

export interface Migration {
    version: number;
    name: string;
    sql: string;
}

/**
 * Ordered, append-only. A migration runs once, inside a transaction, and bumps
 * PRAGMA user_version to its `version`. Never edit a shipped migration: add the
 * next one.
 */
export const MIGRATIONS: readonly Migration[] = [
    { version: 1, name: "initial_schema", sql: V1 },
    { version: 2, name: "health_sync_ledger", sql: V2 },
    { version: 3, name: "dashboard_sessions", sql: V3 },
];

export const SCHEMA_VERSION = MIGRATIONS[MIGRATIONS.length - 1]!.version;

/** The tables after the latest migration (used by tests and the startup audit). */
export const TABLES = [
    "saved_meals",
    "meals",
    "meal_items",
    "saved_meal_items",
    "nutrition_goals",
    "nutrition_goals_history",
    "water_log",
    "weight_log",
    "body_measurement_log",
    "active_calories_log",
    "profiles",
    "food_cache",
    "health_sync_state",
    "health_sync_days",
    "health_sync_sent",
] as const;

/** Tables that hold no owner data (login sessions): excluded from the owner
 *  audit and from delete_account, which is about nutrition data. */
export const INFRA_TABLES = ["dashboard_sessions"] as const;
